391 |     /// @inheritdoc LoanManager
392 |     function validateOffer(bytes calldata _offer, uint256 _protocolFee) external override onlyAcceptedCallers {
393 |         if (!isActive) {
394 |             revert PoolStatusError();
395 |         }
396 |         uint256 currentBalance = asset.balanceOf(address(this)) - getAvailableToWithdraw;
397 |         uint256 baseRateBalance = IBaseInterestAllocator(getBaseInterestAllocator).getAssetsAllocated();
398 |         uint256 undeployedAssets = currentBalance + baseRateBalance;
399 |         (uint256 principalAmount, uint256 apr) = IPoolOfferHandler(getUnderwriter).validateOffer(
400 |             IBaseInterestAllocator(getBaseInterestAllocator).getBaseAprWithUpdate(), _offer
401 |         );
402 | 
403 |         /// @dev Since the balance of the pool includes capital that is waiting to be claimed by the queues,
404 |         ///      we need to check if the pool has enough capital to fund the loan.
405 |         ///      If that's not the case, and the principal is larger than the currentBalance, the we need to reallocate
406 |         ///      part of it.
407 |         if (principalAmount > undeployedAssets) {
408 |             revert InsufficientAssetsError();
409 |         } else if (principalAmount > currentBalance) {
410 |             IBaseInterestAllocator(getBaseInterestAllocator).reallocate(
411 |                 currentBalance, principalAmount - currentBalance, true
412 |             );
413 |         }
414 |         /// @dev If the txn doesn't revert, we can assume the loan was executed.
415 |         _outstandingValues = _getNewLoanAccounting(principalAmount, _netApr(apr, _protocolFee));
416 |     }
